script:
carrier_event = {
	id = distar.13050
	hide_window = yes

	is_triggered_only = yes

	trigger = {
		exists = space_owner
		NOT = { exists = fromfrom } # not surveyed by science ship

		num_deposits > 0 #has_resource is checking the deposits
		OR = {
			AND = {
				NOT = {
					from = { has_country_flag =	exotic_gases_found }
				}
				has_resource = {
					amount > 0
					type = exotic_gases
				}
			}
			AND = {
				NOT = {
					from = { has_country_flag =	rare_crystals_found }
				}
				has_resource = {
					amount > 0
					type = rare_crystals
				}
			}
			AND = {
				NOT = {
					from = { has_country_flag =	volatile_motes_found }
				}
				has_resource = {
					amount > 0
					type = volatile_motes
				}
			}
			AND = {
				NOT = {
					from = { has_country_flag =	sr_living_metal_found }
				}
				has_resource = {
					amount > 0
					type = sr_living_metal
				}
			}
			AND = {
				NOT = {
					from = { has_country_flag =	sr_zro_found }
				}
				has_resource = {
					amount > 0
					type = sr_zro
				}
			}
			AND = {
				NOT = {
					from = { has_country_flag =	sr_dark_matter_found }
				}
				has_resource = {
					amount > 0
					type = sr_dark_matter
				}
			}
		}
	}

	immediate = {

		from = {
			save_event_target_as = finder
			create_message = {
				type = MESSAGE_TYPE_SR_INFORMED
				localization = MESSAGE_SR_INFORMED
				days = 30
				target = root.solar_system # the Go To
				variable = {
					type = name
					localization = PLANET
					scope = root
				}
				variable = {
					type = name
					localization = COUNTRY
					scope = root.space_owner
				}
			}
		}

		if = {
			limit = { has_resource = { type = volatile_motes amount > 0 } }
			from = { set_country_flag =	volatile_motes_found }
		}
		else_if = {
			limit = { has_resource = { type = exotic_gases amount > 0 } }
			from = { set_country_flag =	exotic_gases_found }
		}
		else_if = {
			limit = { has_resource = { type = rare_crystals amount > 0 } }
			from = { set_country_flag =	rare_crystals_found }
		}
		else_if = {
			limit = { has_resource = { type = sr_zro amount > 0 } }
			from = { set_country_flag =	sr_zro_found }
		}
		else_if = {
			limit = { has_resource = { type = sr_dark_matter amount > 0 } }
			from = { set_country_flag =	sr_dark_matter_found }
		}
		else_if = {
			limit = { has_resource = { type = sr_living_metal amount > 0 } }
			from = { set_country_flag =	sr_living_metal_found }
		}
	}
}

